-- =====================================================================
-- Ótica Kadosh — Script SQL completo (Entrega 2)
-- SGBD: MySQL 8.0 (InnoDB, utf8mb4). Testado em banco vazio.
--
-- Ordem do script:
--   1. CREATE DATABASE
--   2. CREATE TABLE (colunas, tipos, PK, NOT NULL, DEFAULT)
--   3. Constraints (UNIQUE, CHECK, FK) e visões
--   4. INSERT INTO (massa de dados fictícia)
--   5. SELECT com JOIN
--   6. UPDATE
--   7. DELETE
--   8. Consultas gerenciais (G01 a G14)
--   9. Consultas de auditoria (A01 a A12)
--
-- Como executar: mysql -u root -p < script.sql
-- (ou abrir no MySQL Workbench e executar tudo). O script recria o banco
-- otica_kadosh do zero: DROP DATABASE IF EXISTS apaga o que existir com esse nome.
-- Os dados são fictícios, sem relação com clientes reais da ótica.
-- =====================================================================


-- =====================================================================
-- 1. CREATE DATABASE
-- =====================================================================
DROP DATABASE IF EXISTS otica_kadosh;
CREATE DATABASE otica_kadosh
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE otica_kadosh;


-- =====================================================================
-- 2. CREATE TABLE
-- Tipos e obrigatoriedade conforme a seção 1.3 do README.
-- UNIQUE, CHECK e FK entram na seção 3 (ALTER TABLE), para ficarem
-- nomeados e ligados à regra de negócio (RNxx) que implementam.
-- =====================================================================

CREATE TABLE CLIENTE (
  ID_CLIENTE           INT          NOT NULL AUTO_INCREMENT,
  NM_CLIENTE           VARCHAR(120) NOT NULL,
  DT_NASCIMENTO        DATE         NULL,
  NR_CPF               CHAR(11)     NULL,
  DS_EMAIL             VARCHAR(120) NULL,
  NR_TELEFONE_FIXO     VARCHAR(11)  NULL,
  NR_TELEFONE_CELULAR  VARCHAR(11)  NULL,
  DS_LOGRADOURO        VARCHAR(120) NULL,
  NR_ENDERECO          VARCHAR(10)  NULL,
  NM_BAIRRO            VARCHAR(60)  NULL,
  NM_CIDADE            VARCHAR(60)  NULL,
  NR_CEP               CHAR(8)      NULL,
  PRIMARY KEY (ID_CLIENTE)
) ENGINE=InnoDB;

CREATE TABLE FUNCIONARIO (
  ID_FUNCIONARIO  INT          NOT NULL AUTO_INCREMENT,
  NM_FUNCIONARIO  VARCHAR(120) NOT NULL,
  TP_FUNCAO       VARCHAR(20)  NOT NULL,
  NR_TELEFONE     VARCHAR(11)  NULL,
  IN_ATIVO        BOOLEAN      NOT NULL DEFAULT TRUE,
  PRIMARY KEY (ID_FUNCIONARIO)
) ENGINE=InnoDB;

CREATE TABLE ATENDIMENTO (
  ID_ATENDIMENTO   INT          NOT NULL AUTO_INCREMENT,
  DH_ATENDIMENTO   DATETIME     NOT NULL,
  TP_MEIO_CONTATO  VARCHAR(30)  NULL,
  TP_ATENDIMENTO   VARCHAR(20)  NOT NULL,
  DS_SERVICO       VARCHAR(255) NULL,
  ID_CLIENTE       INT          NOT NULL,
  ID_FUNCIONARIO   INT          NOT NULL,
  PRIMARY KEY (ID_ATENDIMENTO)
) ENGINE=InnoDB;

CREATE TABLE RECEITA (
  ID_RECEITA      INT          NOT NULL AUTO_INCREMENT,
  DT_RECEITA      DATE         NOT NULL,
  TP_ORIGEM       VARCHAR(11)  NOT NULL,
  DS_OBSERVACAO   VARCHAR(255) NULL,
  ID_ATENDIMENTO  INT          NOT NULL,
  PRIMARY KEY (ID_RECEITA)
) ENGINE=InnoDB;

CREATE TABLE RECEITA_MEDIDA (
  ID_RECEITA          INT           NOT NULL,
  CD_OLHO             CHAR(2)       NOT NULL,
  CD_DISTANCIA        VARCHAR(5)    NOT NULL,
  VL_ESFERICO         DECIMAL(4,2)  NULL,
  VL_CILINDRICO       DECIMAL(4,2)  NULL,
  VL_EIXO             SMALLINT      NULL,
  VL_ACUIDADE_VISUAL  VARCHAR(10)   NULL,
  VL_DNP              DECIMAL(4,1)  NULL,
  VL_ALTURA           DECIMAL(4,1)  NULL,
  PRIMARY KEY (ID_RECEITA, CD_OLHO, CD_DISTANCIA)
) ENGINE=InnoDB;

CREATE TABLE ORCAMENTO (
  ID_ORCAMENTO    INT          NOT NULL AUTO_INCREMENT,
  DH_EMISSAO      DATETIME     NOT NULL,
  DH_VALIDADE     DATETIME     NOT NULL,
  DH_APROVACAO    DATETIME     NULL,
  CD_STATUS       VARCHAR(15)  NOT NULL,
  DS_OBSERVACAO   VARCHAR(255) NULL,
  ID_ATENDIMENTO  INT          NOT NULL,
  PRIMARY KEY (ID_ORCAMENTO)
) ENGINE=InnoDB;

CREATE TABLE VENDA (
  ID_VENDA                     INT          NOT NULL AUTO_INCREMENT,
  DH_COMPRA                    DATETIME     NOT NULL,
  CD_STATUS                    VARCHAR(20)  NOT NULL,
  DS_OBSERVACAO                VARCHAR(255) NULL,
  DT_MONTAGEM_FINALIZACAO      DATE         NULL,
  DT_RETIRADA                  DATE         NULL,
  HR_PREVISTA_RETIRADA         TIME         NULL,
  DT_PREVISTA_CONCLUSAO        DATE         NULL,
  DT_LIBERACAO_ENCOMENDA       DATE         NULL,
  IN_CANHOTO_CONFERIDO         BOOLEAN      NULL,
  DH_ENVIO_FORNECEDOR          DATETIME     NULL,
  DH_SOLICITACAO_CANCELAMENTO  DATETIME     NULL,
  ID_ATENDIMENTO               INT          NOT NULL,
  PRIMARY KEY (ID_VENDA)
) ENGINE=InnoDB;

CREATE TABLE PRODUTO (
  ID_PRODUTO     INT          NOT NULL AUTO_INCREMENT,
  CD_TIPO        VARCHAR(10)  NOT NULL,
  DS_REFERENCIA  VARCHAR(60)  NOT NULL,
  NM_MARCA       VARCHAR(60)  NULL,
  PRIMARY KEY (ID_PRODUTO)
) ENGINE=InnoDB;

CREATE TABLE LENTE (
  ID_PRODUTO      INT          NOT NULL,
  CD_TIPO         VARCHAR(10)  NOT NULL DEFAULT 'LENTE',
  VL_INDICE       DECIMAL(3,2) NULL,
  DS_TRATAMENTO   VARCHAR(60)  NULL,
  IN_POSSUI_GRAU  BOOLEAN      NOT NULL,
  PRIMARY KEY (ID_PRODUTO)
) ENGINE=InnoDB;

CREATE TABLE ARMACAO (
  ID_PRODUTO   INT          NOT NULL,
  CD_TIPO      VARCHAR(10)  NOT NULL DEFAULT 'ARMACAO',
  TP_ARMACAO   VARCHAR(40)  NULL,
  DS_MATERIAL  VARCHAR(40)  NULL,
  PRIMARY KEY (ID_PRODUTO)
) ENGINE=InnoDB;

CREATE TABLE CONTEM (
  ID_VENDA           INT           NOT NULL,
  NR_LINHA           SMALLINT      NOT NULL,
  QT_PRODUTO         INT           NOT NULL,
  VL_PRECO_UNITARIO  DECIMAL(10,2) NOT NULL,
  DS_OBSERVACAO      VARCHAR(255)  NULL,
  ID_PRODUTO         INT           NOT NULL,
  PRIMARY KEY (ID_VENDA, NR_LINHA)
) ENGINE=InnoDB;

CREATE TABLE PARCELA (
  ID_PARCELA     INT           NOT NULL AUTO_INCREMENT,
  NR_PARCELA     SMALLINT      NOT NULL,
  VL_PARCELA     DECIMAL(10,2) NOT NULL,
  DT_VENCIMENTO  DATE          NOT NULL,
  PRIMARY KEY (ID_PARCELA)
) ENGINE=InnoDB;

CREATE TABLE PAGAMENTO (
  ID_PAGAMENTO        INT           NOT NULL AUTO_INCREMENT,
  VL_PAGAMENTO        DECIMAL(10,2) NOT NULL,
  DT_PAGAMENTO        DATE          NOT NULL,
  TP_FORMA            VARCHAR(10)   NOT NULL,
  TP_FINALIDADE       VARCHAR(20)   NOT NULL,
  ID_VENDA            INT           NOT NULL,
  ID_PARCELA_QUITADA  INT           NULL,
  PRIMARY KEY (ID_PAGAMENTO)
) ENGINE=InnoDB;

CREATE TABLE NOTA_FISCAL_SAIDA (
  ID_NOTA_SAIDA  INT           NOT NULL AUTO_INCREMENT,
  NR_NOTA        VARCHAR(20)   NOT NULL,
  DT_EMISSAO     DATE          NOT NULL,
  VL_TOTAL       DECIMAL(12,2) NOT NULL,
  VL_TRIBUTOS    DECIMAL(12,2) NULL,
  ID_PAGAMENTO   INT           NOT NULL,
  PRIMARY KEY (ID_NOTA_SAIDA)
) ENGINE=InnoDB;

CREATE TABLE FORNECEDOR (
  ID_FORNECEDOR  INT          NOT NULL AUTO_INCREMENT,
  NM_FORNECEDOR  VARCHAR(120) NOT NULL,
  NR_CNPJ        VARCHAR(14)  NULL,
  DS_ENDERECO    VARCHAR(200) NULL,
  DS_CONTATO     VARCHAR(120) NULL,
  PRIMARY KEY (ID_FORNECEDOR)
) ENGINE=InnoDB;

CREATE TABLE COMPRA (
  ID_COMPRA      INT          NOT NULL AUTO_INCREMENT,
  DT_PEDIDO      DATE         NOT NULL,
  DT_CHEGADA     DATE         NULL,
  CD_STATUS      VARCHAR(15)  NOT NULL,
  ID_FORNECEDOR  INT          NOT NULL,
  ID_VENDA       INT          NULL,
  PRIMARY KEY (ID_COMPRA)
) ENGINE=InnoDB;

CREATE TABLE NOTA_FISCAL_ENTRADA (
  ID_NOTA_ENTRADA  INT           NOT NULL AUTO_INCREMENT,
  NR_NOTA          VARCHAR(20)   NOT NULL,
  DT_EMISSAO       DATE          NOT NULL,
  VL_TOTAL         DECIMAL(12,2) NOT NULL,
  VL_TRIBUTOS      DECIMAL(12,2) NULL,
  ID_COMPRA        INT           NOT NULL,
  PRIMARY KEY (ID_NOTA_ENTRADA)
) ENGINE=InnoDB;

CREATE TABLE TROCA_DEVOLUCAO (
  ID_OCORRENCIA         INT           NOT NULL AUTO_INCREMENT,
  TP_OCORRENCIA         VARCHAR(10)   NOT NULL,
  DT_OCORRIDO           DATE          NOT NULL,
  CD_STATUS             VARCHAR(15)   NOT NULL,
  QT_AFETADA            INT           NOT NULL,
  DS_DANO               VARCHAR(255)  NULL,
  DS_PARECER_AVALIACAO  VARCHAR(255)  NULL,
  DT_AVALIACAO          DATE          NULL,
  VL_COBRADO            DECIMAL(10,2) NULL,
  VL_ABATIMENTO         DECIMAL(10,2) NULL,
  VL_REEMBOLSADO        DECIMAL(10,2) NULL,
  DT_REEMBOLSO          DATE          NULL,
  ID_NOTA_SAIDA         INT           NOT NULL,
  PRIMARY KEY (ID_OCORRENCIA)
) ENGINE=InnoDB;

CREATE TABLE ESTOQUE (
  ID_MOVIMENTO  INT          NOT NULL AUTO_INCREMENT,
  DT_MOVIMENTO  DATE         NOT NULL,
  QT_MOVIMENTO  INT          NOT NULL,
  CD_DIRECAO    VARCHAR(7)   NOT NULL,
  CD_MOTIVO     VARCHAR(25)  NOT NULL,
  CD_CONDICAO   VARCHAR(12)  NOT NULL,
  ID_PRODUTO    INT          NOT NULL,
  ID_COMPRA     INT          NULL,
  PRIMARY KEY (ID_MOVIMENTO)
) ENGINE=InnoDB;


-- =====================================================================
-- 3. CONSTRAINTS
-- Cada restrição cita a regra de negócio que implementa (seção 1.5 do
-- README). Convenção de nomes: uq_ (unicidade), ck_ (CHECK), fk_ (FK).
-- Todas as FKs usam ON DELETE RESTRICT e ON UPDATE RESTRICT: nada é
-- apagado ou renumerado quando existe registro dependente (histórico).
-- =====================================================================

-- 3.1 Unicidade -------------------------------------------------------
ALTER TABLE CLIENTE              ADD CONSTRAINT uq_cliente_cpf         UNIQUE (NR_CPF);                  -- cadastro sem duplicidade; CPF opcional
ALTER TABLE FORNECEDOR           ADD CONSTRAINT uq_fornecedor_cnpj     UNIQUE (NR_CNPJ);                 -- cadastro sem duplicidade; CNPJ opcional
ALTER TABLE RECEITA              ADD CONSTRAINT uq_receita_atend       UNIQUE (ID_ATENDIMENTO);          -- RN-02: uma receita por atendimento
ALTER TABLE VENDA                ADD CONSTRAINT uq_venda_atend         UNIQUE (ID_ATENDIMENTO);          -- RN-01: no máximo uma venda por atendimento
ALTER TABLE PAGAMENTO            ADD CONSTRAINT uq_pagamento_parcela   UNIQUE (ID_PARCELA_QUITADA);      -- RN-28: parcela quitada por no máximo um pagamento
ALTER TABLE NOTA_FISCAL_SAIDA    ADD CONSTRAINT uq_nfs_pagamento       UNIQUE (ID_PAGAMENTO);            -- RN-22: uma nota por pagamento
ALTER TABLE NOTA_FISCAL_ENTRADA  ADD CONSTRAINT uq_nfe_compra          UNIQUE (ID_COMPRA);               -- RN-35: uma nota por compra
ALTER TABLE PRODUTO              ADD CONSTRAINT uq_produto_tipo        UNIQUE (ID_PRODUTO, CD_TIPO);     -- RN-14: permite a FK composta das especializações

-- 3.2 Chaves estrangeiras --------------------------------------------
ALTER TABLE ATENDIMENTO ADD CONSTRAINT fk_atend_cliente      FOREIGN KEY (ID_CLIENTE)     REFERENCES CLIENTE (ID_CLIENTE)         ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE ATENDIMENTO ADD CONSTRAINT fk_atend_funcionario  FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO (ID_FUNCIONARIO) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE RECEITA     ADD CONSTRAINT fk_receita_atend      FOREIGN KEY (ID_ATENDIMENTO) REFERENCES ATENDIMENTO (ID_ATENDIMENTO) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE RECEITA_MEDIDA ADD CONSTRAINT fk_medida_receita  FOREIGN KEY (ID_RECEITA)     REFERENCES RECEITA (ID_RECEITA)         ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE ORCAMENTO   ADD CONSTRAINT fk_orc_atend          FOREIGN KEY (ID_ATENDIMENTO) REFERENCES ATENDIMENTO (ID_ATENDIMENTO) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE VENDA       ADD CONSTRAINT fk_venda_atend        FOREIGN KEY (ID_ATENDIMENTO) REFERENCES ATENDIMENTO (ID_ATENDIMENTO) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE CONTEM      ADD CONSTRAINT fk_contem_venda       FOREIGN KEY (ID_VENDA)       REFERENCES VENDA (ID_VENDA)             ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE CONTEM      ADD CONSTRAINT fk_contem_produto     FOREIGN KEY (ID_PRODUTO)     REFERENCES PRODUTO (ID_PRODUTO)         ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE LENTE       ADD CONSTRAINT fk_lente_produto      FOREIGN KEY (ID_PRODUTO, CD_TIPO) REFERENCES PRODUTO (ID_PRODUTO, CD_TIPO) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE ARMACAO     ADD CONSTRAINT fk_armacao_produto    FOREIGN KEY (ID_PRODUTO, CD_TIPO) REFERENCES PRODUTO (ID_PRODUTO, CD_TIPO) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE PAGAMENTO   ADD CONSTRAINT fk_pag_venda          FOREIGN KEY (ID_VENDA)       REFERENCES VENDA (ID_VENDA)             ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE PAGAMENTO   ADD CONSTRAINT fk_pag_parcela        FOREIGN KEY (ID_PARCELA_QUITADA) REFERENCES PARCELA (ID_PARCELA)     ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE NOTA_FISCAL_SAIDA ADD CONSTRAINT fk_nfs_pagamento FOREIGN KEY (ID_PAGAMENTO)  REFERENCES PAGAMENTO (ID_PAGAMENTO)     ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE TROCA_DEVOLUCAO ADD CONSTRAINT fk_troca_nfs      FOREIGN KEY (ID_NOTA_SAIDA)  REFERENCES NOTA_FISCAL_SAIDA (ID_NOTA_SAIDA) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE COMPRA      ADD CONSTRAINT fk_compra_fornecedor  FOREIGN KEY (ID_FORNECEDOR)  REFERENCES FORNECEDOR (ID_FORNECEDOR)   ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE COMPRA      ADD CONSTRAINT fk_compra_venda       FOREIGN KEY (ID_VENDA)       REFERENCES VENDA (ID_VENDA)             ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE NOTA_FISCAL_ENTRADA ADD CONSTRAINT fk_nfe_compra FOREIGN KEY (ID_COMPRA)      REFERENCES COMPRA (ID_COMPRA)           ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE ESTOQUE     ADD CONSTRAINT fk_estoque_produto    FOREIGN KEY (ID_PRODUTO)     REFERENCES PRODUTO (ID_PRODUTO)         ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE ESTOQUE     ADD CONSTRAINT fk_estoque_compra     FOREIGN KEY (ID_COMPRA)      REFERENCES COMPRA (ID_COMPRA)           ON DELETE RESTRICT ON UPDATE RESTRICT;

-- 3.3 Valores permitidos e coerência entre colunas (CHECK) -----------
ALTER TABLE CLIENTE ADD CONSTRAINT ck_cliente_cep
  CHECK (NR_CEP IS NULL OR NR_CEP REGEXP '^[0-9]{8}$');                                                         -- formato fixo do CEP

ALTER TABLE FUNCIONARIO ADD CONSTRAINT ck_func_funcao
  CHECK (TP_FUNCAO IN ('OPTOMETRISTA','GERENTE','CONSULTOR_OPTICO'));                                           -- RN-15

ALTER TABLE ATENDIMENTO ADD CONSTRAINT ck_atend_tipo
  CHECK (TP_ATENDIMENTO IN ('COMERCIAL','AVALIACAO','MANUTENCAO'));                                             -- RN-20

ALTER TABLE RECEITA ADD CONSTRAINT ck_receita_origem
  CHECK (TP_ORIGEM IN ('TRAZIDA','LAUDO_OTICA'));                                                               -- RN-03, RN-15

ALTER TABLE RECEITA_MEDIDA ADD CONSTRAINT ck_medida_olho       CHECK (CD_OLHO IN ('OD','OE'));                  -- RN-10
ALTER TABLE RECEITA_MEDIDA ADD CONSTRAINT ck_medida_distancia  CHECK (CD_DISTANCIA IN ('LONGE','PERTO'));       -- RN-10
ALTER TABLE RECEITA_MEDIDA ADD CONSTRAINT ck_medida_eixo       CHECK (VL_EIXO IS NULL OR VL_EIXO BETWEEN 0 AND 180); -- RN-10

ALTER TABLE ORCAMENTO ADD CONSTRAINT ck_orc_status
  CHECK (CD_STATUS IN ('EM_ELABORACAO','EMITIDO','APROVADO','RECUSADO','CANCELADO'));                           -- RN-23
ALTER TABLE ORCAMENTO ADD CONSTRAINT ck_orc_validade   CHECK (DH_VALIDADE > DH_EMISSAO);                        -- RN-23
ALTER TABLE ORCAMENTO ADD CONSTRAINT ck_orc_aprovacao  CHECK (CD_STATUS <> 'APROVADO' OR DH_APROVACAO IS NOT NULL); -- RN-23

ALTER TABLE VENDA ADD CONSTRAINT ck_venda_status
  CHECK (CD_STATUS IN ('ABERTO','AGUARDANDO_PRODUTO','EM_MONTAGEM','PRONTO','RETIRADO','CANCELADO'));           -- RN-24
ALTER TABLE VENDA ADD CONSTRAINT ck_venda_liberacao
  CHECK (DT_LIBERACAO_ENCOMENDA IS NULL OR DT_PREVISTA_CONCLUSAO IS NOT NULL);                                  -- RN-18
ALTER TABLE VENDA ADD CONSTRAINT ck_venda_retirada
  CHECK (DT_RETIRADA IS NULL OR IN_CANHOTO_CONFERIDO = TRUE);                                                   -- RN-21

ALTER TABLE CONTEM ADD CONSTRAINT ck_contem_qt     CHECK (QT_PRODUTO > 0);                                      -- RN-04
ALTER TABLE CONTEM ADD CONSTRAINT ck_contem_preco  CHECK (VL_PRECO_UNITARIO >= 0);                             -- RN-04

ALTER TABLE PRODUTO ADD CONSTRAINT ck_produto_tipo CHECK (CD_TIPO IN ('LENTE','ARMACAO'));                      -- RN-14
ALTER TABLE LENTE   ADD CONSTRAINT ck_lente_tipo   CHECK (CD_TIPO = 'LENTE');                                   -- RN-14
ALTER TABLE ARMACAO ADD CONSTRAINT ck_armacao_tipo CHECK (CD_TIPO = 'ARMACAO');                                 -- RN-14
ALTER TABLE LENTE   ADD CONSTRAINT ck_lente_indice CHECK (VL_INDICE IS NULL OR VL_INDICE > 0);                  -- RN-27

ALTER TABLE PAGAMENTO ADD CONSTRAINT ck_pag_valor     CHECK (VL_PAGAMENTO > 0);                                 -- RN-11
ALTER TABLE PAGAMENTO ADD CONSTRAINT ck_pag_forma     CHECK (TP_FORMA IN ('PIX','DINHEIRO','DEBITO','CREDITO'));
ALTER TABLE PAGAMENTO ADD CONSTRAINT ck_pag_finalidade
  CHECK (TP_FINALIDADE IN ('SINAL','INTEGRAL','PARCIAL','QUITACAO_PARCELA'));                                   -- RN-05, RN-18
ALTER TABLE PAGAMENTO ADD CONSTRAINT ck_pag_quitacao
  CHECK ((TP_FINALIDADE = 'QUITACAO_PARCELA') = (ID_PARCELA_QUITADA IS NOT NULL));                              -- RN-28

ALTER TABLE PARCELA ADD CONSTRAINT ck_parcela_numero CHECK (NR_PARCELA BETWEEN 1 AND 10);                       -- RN-17
ALTER TABLE PARCELA ADD CONSTRAINT ck_parcela_valor  CHECK (VL_PARCELA >= 50);                                  -- RN-17

ALTER TABLE NOTA_FISCAL_SAIDA   ADD CONSTRAINT ck_nfs_total CHECK (VL_TOTAL >= 0);                              -- RN-22
ALTER TABLE NOTA_FISCAL_ENTRADA ADD CONSTRAINT ck_nfe_total CHECK (VL_TOTAL >= 0);                              -- RN-35

ALTER TABLE COMPRA ADD CONSTRAINT ck_compra_status  CHECK (CD_STATUS IN ('SOLICITADA','RECEBIDA','CANCELADA')); -- RN-06
ALTER TABLE COMPRA ADD CONSTRAINT ck_compra_chegada CHECK (DT_CHEGADA IS NULL OR DT_CHEGADA >= DT_PEDIDO);      -- RN-06

ALTER TABLE TROCA_DEVOLUCAO ADD CONSTRAINT ck_troca_tipo   CHECK (TP_OCORRENCIA IN ('TROCA','DEVOLUCAO'));       -- RN-25
ALTER TABLE TROCA_DEVOLUCAO ADD CONSTRAINT ck_troca_status
  CHECK (CD_STATUS IN ('ABERTA','EM_AVALIACAO','APROVADA','RECUSADA','CONCLUIDA'));                             -- RN-25
ALTER TABLE TROCA_DEVOLUCAO ADD CONSTRAINT ck_troca_qt     CHECK (QT_AFETADA > 0);                              -- RN-25
ALTER TABLE TROCA_DEVOLUCAO ADD CONSTRAINT ck_troca_parecer
  CHECK (CD_STATUS NOT IN ('APROVADA','RECUSADA') OR (DS_PARECER_AVALIACAO IS NOT NULL AND DT_AVALIACAO IS NOT NULL)); -- RN-25
ALTER TABLE TROCA_DEVOLUCAO ADD CONSTRAINT ck_troca_valores
  CHECK ((VL_COBRADO IS NULL OR VL_COBRADO >= 0) AND (VL_ABATIMENTO IS NULL OR VL_ABATIMENTO >= 0)
         AND (VL_REEMBOLSADO IS NULL OR VL_REEMBOLSADO >= 0));                                                  -- RN-33

ALTER TABLE ESTOQUE ADD CONSTRAINT ck_estoque_qt       CHECK (QT_MOVIMENTO > 0);                                -- RN-12
ALTER TABLE ESTOQUE ADD CONSTRAINT ck_estoque_direcao  CHECK (CD_DIRECAO IN ('ENTRADA','SAIDA'));               -- RN-12
ALTER TABLE ESTOQUE ADD CONSTRAINT ck_estoque_motivo
  CHECK (CD_MOTIVO IN ('COMPRA','VENDA','REAPROVEITAMENTO','DEVOLUCAO_AVARIA','DESCARTE','SUBSTITUICAO'));      -- RN-12
ALTER TABLE ESTOQUE ADD CONSTRAINT ck_estoque_condicao CHECK (CD_CONDICAO IN ('DISPONIVEL','SEGREGADO'));       -- RN-12
ALTER TABLE ESTOQUE ADD CONSTRAINT ck_estoque_compat                                                            -- RN-12: motivo, direção e condição compatíveis
  CHECK ((CD_MOTIVO = 'COMPRA'           AND CD_DIRECAO = 'ENTRADA' AND CD_CONDICAO = 'DISPONIVEL')
      OR (CD_MOTIVO = 'VENDA'            AND CD_DIRECAO = 'SAIDA'   AND CD_CONDICAO = 'DISPONIVEL')
      OR (CD_MOTIVO = 'REAPROVEITAMENTO' AND CD_DIRECAO = 'ENTRADA' AND CD_CONDICAO = 'DISPONIVEL')
      OR (CD_MOTIVO = 'DEVOLUCAO_AVARIA' AND CD_DIRECAO = 'ENTRADA' AND CD_CONDICAO = 'SEGREGADO')
      OR (CD_MOTIVO = 'DESCARTE'         AND CD_DIRECAO = 'SAIDA'   AND CD_CONDICAO = 'SEGREGADO')
      OR (CD_MOTIVO = 'SUBSTITUICAO'     AND CD_DIRECAO = 'SAIDA'   AND CD_CONDICAO = 'DISPONIVEL'));
ALTER TABLE ESTOQUE ADD CONSTRAINT ck_estoque_compra                                                            -- RN-30
  CHECK ((CD_MOTIVO = 'COMPRA') = (ID_COMPRA IS NOT NULL));

-- 3.4 Índices de apoio às consultas (além dos criados pelas FKs) -----
CREATE INDEX idx_atend_data      ON ATENDIMENTO (DH_ATENDIMENTO);
CREATE INDEX idx_venda_data      ON VENDA (DH_COMPRA);
CREATE INDEX idx_pag_venda_data  ON PAGAMENTO (ID_VENDA, DT_PAGAMENTO);
CREATE INDEX idx_estoque_prod    ON ESTOQUE (ID_PRODUTO, DT_MOVIMENTO);
CREATE INDEX idx_parcela_venc    ON PARCELA (DT_VENCIMENTO);

-- 3.5 Visões dos valores calculáveis (seção 1.4 do README) -----------
-- O total da venda, a situação da parcela e a unidade do produto não
-- são gravados: ficam nestas visões, com uma única fonte para cada dado.

-- Total da venda = soma de quantidade x preço praticado das linhas (RN-04)
CREATE VIEW vw_venda_total AS
SELECT v.ID_VENDA,
       COALESCE(SUM(c.QT_PRODUTO * c.VL_PRECO_UNITARIO), 0) AS VL_TOTAL
  FROM VENDA v
  LEFT JOIN CONTEM c ON c.ID_VENDA = v.ID_VENDA
 GROUP BY v.ID_VENDA;

-- Situação da parcela (RN-28): PAGA se há pagamento ligado; ATRASADA se
-- não há e o vencimento passou; ABERTA nos demais casos.
CREATE VIEW vw_parcela_situacao AS
SELECT p.ID_PARCELA, p.NR_PARCELA, p.VL_PARCELA, p.DT_VENCIMENTO,
       g.ID_PAGAMENTO,
       g.DT_PAGAMENTO AS DT_QUITACAO,
       CASE WHEN g.ID_PAGAMENTO IS NOT NULL THEN 'PAGA'
            WHEN p.DT_VENCIMENTO < CURDATE()  THEN 'ATRASADA'
            ELSE 'ABERTA' END AS CD_SITUACAO
  FROM PARCELA p
  LEFT JOIN PAGAMENTO g ON g.ID_PARCELA_QUITADA = p.ID_PARCELA;

-- Unidade de contagem do estoque (RN-26): lente em par, armação em unidade
CREATE VIEW vw_produto_unidade AS
SELECT ID_PRODUTO, CD_TIPO, DS_REFERENCIA, NM_MARCA,
       CASE CD_TIPO WHEN 'LENTE' THEN 'PAR' ELSE 'UNIDADE' END AS CD_UNIDADE
  FROM PRODUTO;


-- =====================================================================
-- 4. INSERT INTO — MASSA DE DADOS FICTÍCIA
-- Tudo é inventado (nomes, CPF, CNPJ, telefones e e-mails example.com): nenhum
-- dado de cliente, funcionário ou fornecedor reais da ótica.
-- Período: 01/09/2026 a 30/10/2026, com os volumes da seção 1.1 do README:
-- ≈ 100 atendimentos e ≈ 80 vendas efetivas por semana, ≈ 12 compras por mês e
-- ≈ 4% de trocas e devoluções. Há também uma amostra de vendas antigas
-- (maio/2026 e novembro/2025, sem movimento de estoque), para os testes de
-- garantia e de períodos diferentes.
-- Casos de teste incluídos de propósito: vendas canceladas, clientes sem compra,
-- orçamentos recusados, parcelas pagas, abertas e atrasadas, lentes abaixo do
-- mínimo, produtos sem saldo, compras ainda não recebidas, trocas e devoluções em
-- todas as etapas e 21 violações propositais de regra, para as consultas de
-- auditoria A01 a A12 terem o que encontrar.
-- Gerada por programa com semente fixa (ver seção 6 do README, uso de IA).
-- =====================================================================
SET NAMES utf8mb4;

-- FUNCIONARIO: 4 linhas

-- CLIENTE: 900 linhas

-- FORNECEDOR: 6 linhas

-- PRODUTO: 351 linhas

-- LENTE: 120 linhas

-- ARMACAO: 230 linhas

-- ATENDIMENTO: 885 linhas

-- RECEITA: 625 linhas

-- RECEITA_MEDIDA: 1569 linhas

-- ORCAMENTO: 862 linhas

-- VENDA: 740 linhas

-- CONTEM: 1402 linhas

-- PARCELA: 850 linhas

-- PAGAMENTO: 846 linhas

-- NOTA_FISCAL_SAIDA: 844 linhas

-- TROCA_DEVOLUCAO: 31 linhas

-- COMPRA: 30 linhas

-- NOTA_FISCAL_ENTRADA: 28 linhas

-- ESTOQUE: 2235 linhas


-- =====================================================================
-- Data de referência das consultas
-- A demonstração usa a data da carga (30/10/2026), para que os resultados
-- sejam sempre os mesmos. Em produção, troque por: SET @hoje = CURDATE();
-- @ini é o início do período coberto pela massa de dados (a amostra de
-- vendas antigas de 2025 e maio/2026 serve só para garantias e períodos).
-- =====================================================================
SET @hoje = '2026-10-30';
SET @ini  = '2026-09-01';


-- =====================================================================
-- 5. SELECT COM JOIN
-- Consultas de uso diário que cruzam várias tabelas (códigos J01 a J06).
-- =====================================================================

-- J01 — Quais clientes foram mais atendidos no período e com quem?
-- Cruza: CLIENTE, ATENDIMENTO, FUNCIONARIO
SELECT c.ID_CLIENTE, c.NM_CLIENTE, COUNT(*) AS atendimentos,
       MIN(a.DH_ATENDIMENTO) AS primeiro, MAX(a.DH_ATENDIMENTO) AS ultimo,
       GROUP_CONCAT(DISTINCT f.NM_FUNCIONARIO ORDER BY f.NM_FUNCIONARIO SEPARATOR ', ') AS atendido_por
  FROM CLIENTE c
  JOIN ATENDIMENTO a ON a.ID_CLIENTE = c.ID_CLIENTE
  JOIN FUNCIONARIO f ON f.ID_FUNCIONARIO = a.ID_FUNCIONARIO
 WHERE a.DH_ATENDIMENTO >= @ini
 GROUP BY c.ID_CLIENTE, c.NM_CLIENTE
 ORDER BY atendimentos DESC, c.NM_CLIENTE
 LIMIT 10;

-- J02 — Quais são as linhas das últimas vendas, com o produto e as características do subtipo?
-- Cruza: VENDA, CONTEM, PRODUTO, LENTE, ARMACAO
SELECT v.ID_VENDA, v.DH_COMPRA, ct.NR_LINHA, p.CD_TIPO, p.DS_REFERENCIA, p.NM_MARCA,
       COALESCE(CONCAT('índice ', l.VL_INDICE, ' / ', COALESCE(l.DS_TRATAMENTO, 'sem tratamento')),
                CONCAT(ar.TP_ARMACAO, ' / ', ar.DS_MATERIAL)) AS caracteristicas,
       ct.QT_PRODUTO, ct.VL_PRECO_UNITARIO, ct.QT_PRODUTO * ct.VL_PRECO_UNITARIO AS subtotal
  FROM VENDA v
  JOIN CONTEM ct   ON ct.ID_VENDA = v.ID_VENDA
  JOIN PRODUTO p   ON p.ID_PRODUTO = ct.ID_PRODUTO
  LEFT JOIN LENTE l   ON l.ID_PRODUTO = p.ID_PRODUTO
  LEFT JOIN ARMACAO ar ON ar.ID_PRODUTO = p.ID_PRODUTO
 WHERE v.ID_VENDA IN (SELECT ID_VENDA FROM (SELECT ID_VENDA FROM VENDA ORDER BY DH_COMPRA DESC LIMIT 5) ult)
 ORDER BY v.DH_COMPRA DESC, ct.NR_LINHA;

-- J03 — Quais vendas foram retiradas na última semana, com cliente, consultor e valor total?
-- Cruza: VENDA, ATENDIMENTO, CLIENTE, FUNCIONARIO, vw_venda_total
SELECT v.ID_VENDA, v.DT_RETIRADA, c.NM_CLIENTE, f.NM_FUNCIONARIO AS consultor, t.VL_TOTAL
  FROM VENDA v
  JOIN ATENDIMENTO a   ON a.ID_ATENDIMENTO = v.ID_ATENDIMENTO
  JOIN CLIENTE c       ON c.ID_CLIENTE = a.ID_CLIENTE
  JOIN FUNCIONARIO f   ON f.ID_FUNCIONARIO = a.ID_FUNCIONARIO
  JOIN vw_venda_total t ON t.ID_VENDA = v.ID_VENDA
 WHERE v.CD_STATUS = 'RETIRADO'
   AND v.DT_RETIRADA BETWEEN DATE_SUB(@hoje, INTERVAL 7 DAY) AND @hoje
 ORDER BY v.DT_RETIRADA DESC, v.ID_VENDA
 LIMIT 15;

-- J04 — Quais são a receita e as medidas de um atendimento? (dado de saúde: acesso restrito, RNF-01)
-- Cruza: ATENDIMENTO, CLIENTE, RECEITA, RECEITA_MEDIDA
SELECT a.ID_ATENDIMENTO, c.NM_CLIENTE, r.DT_RECEITA, r.TP_ORIGEM,
       m.CD_OLHO, m.CD_DISTANCIA, m.VL_ESFERICO, m.VL_CILINDRICO, m.VL_EIXO, m.VL_DNP, m.VL_ALTURA
  FROM ATENDIMENTO a
  JOIN CLIENTE c         ON c.ID_CLIENTE = a.ID_CLIENTE
  JOIN RECEITA r         ON r.ID_ATENDIMENTO = a.ID_ATENDIMENTO
  JOIN RECEITA_MEDIDA m  ON m.ID_RECEITA = r.ID_RECEITA
 WHERE a.ID_ATENDIMENTO = (SELECT MAX(r2.ID_ATENDIMENTO) FROM RECEITA r2 JOIN RECEITA_MEDIDA m2 ON m2.ID_RECEITA = r2.ID_RECEITA)
 ORDER BY m.CD_DISTANCIA, m.CD_OLHO;

-- J05 — Como ficaram os pagamentos de uma venda parcelada, com nota fiscal e parcela quitada?
-- Cruza: VENDA, PAGAMENTO, NOTA_FISCAL_SAIDA, PARCELA
SELECT p.ID_PAGAMENTO, p.DT_PAGAMENTO, p.TP_FINALIDADE, p.TP_FORMA, p.VL_PAGAMENTO,
       n.NR_NOTA, pa.NR_PARCELA, pa.DT_VENCIMENTO
  FROM PAGAMENTO p
  JOIN VENDA v                    ON v.ID_VENDA = p.ID_VENDA
  LEFT JOIN NOTA_FISCAL_SAIDA n   ON n.ID_PAGAMENTO = p.ID_PAGAMENTO
  LEFT JOIN PARCELA pa            ON pa.ID_PARCELA = p.ID_PARCELA_QUITADA
 WHERE p.ID_VENDA = (SELECT MIN(p2.ID_VENDA) FROM PAGAMENTO p2 WHERE p2.TP_FINALIDADE = 'QUITACAO_PARCELA')
 ORDER BY p.DT_PAGAMENTO, p.ID_PAGAMENTO;

-- J06 — Quais produtos entraram no estoque em cada compra recebida, com fornecedor e nota de entrada?
-- Cruza: COMPRA, FORNECEDOR, NOTA_FISCAL_ENTRADA, ESTOQUE, PRODUTO
SELECT c.ID_COMPRA, c.DT_PEDIDO, c.DT_CHEGADA, f.NM_FORNECEDOR, n.NR_NOTA,
       COUNT(e.ID_MOVIMENTO) AS produtos_recebidos, SUM(e.QT_MOVIMENTO) AS unidades_recebidas
  FROM COMPRA c
  JOIN FORNECEDOR f                ON f.ID_FORNECEDOR = c.ID_FORNECEDOR
  LEFT JOIN NOTA_FISCAL_ENTRADA n  ON n.ID_COMPRA = c.ID_COMPRA
  LEFT JOIN ESTOQUE e              ON e.ID_COMPRA = c.ID_COMPRA
  LEFT JOIN PRODUTO p              ON p.ID_PRODUTO = e.ID_PRODUTO
 WHERE c.DT_PEDIDO >= @ini
 GROUP BY c.ID_COMPRA, c.DT_PEDIDO, c.DT_CHEGADA, f.NM_FORNECEDOR, n.NR_NOTA
 ORDER BY c.DT_PEDIDO, c.ID_COMPRA;


-- =====================================================================
-- 6. UPDATE
-- Alterações de rotina que respeitam as restrições do modelo.
-- =====================================================================

-- U01 — Registrar a retirada de uma venda pronta (RN-21: exige o canhoto conferido).
UPDATE VENDA
   SET CD_STATUS = 'RETIRADO', DT_RETIRADA = @hoje, IN_CANHOTO_CONFERIDO = TRUE
 WHERE CD_STATUS = 'PRONTO'
 ORDER BY DT_MONTAGEM_FINALIZACAO, ID_VENDA
 LIMIT 1;

-- U02 — Corrigir o celular de uma cliente.
UPDATE CLIENTE
   SET NR_TELEFONE_CELULAR = '11977776666'
 WHERE ID_CLIENTE = 1;

-- U03 — Reprogramar a previsão de conclusão de uma encomenda por atraso do fornecedor (+2 dias).
UPDATE VENDA
   SET DT_PREVISTA_CONCLUSAO = DATE_ADD(DT_PREVISTA_CONCLUSAO, INTERVAL 2 DAY)
 WHERE CD_STATUS = 'AGUARDANDO_PRODUTO'
 ORDER BY DT_PREVISTA_CONCLUSAO, ID_VENDA
 LIMIT 1;

-- Conferência dos três UPDATE
SELECT ID_VENDA, CD_STATUS, DT_RETIRADA, IN_CANHOTO_CONFERIDO, DT_PREVISTA_CONCLUSAO
  FROM VENDA
 WHERE (CD_STATUS = 'RETIRADO' AND DT_RETIRADA = @hoje) OR CD_STATUS = 'AGUARDANDO_PRODUTO'
 ORDER BY DT_PREVISTA_CONCLUSAO LIMIT 5;


-- =====================================================================
-- 7. DELETE
-- Com ON DELETE RESTRICT, só se apaga o que não tem registro dependente.
-- O histórico (atendimentos, vendas, pagamentos) nunca é apagado.
-- =====================================================================

-- D01 — Excluir um cadastro de cliente criado por engano, sem nenhum atendimento.
DELETE FROM CLIENTE
 WHERE ID_CLIENTE = 900
   AND NOT EXISTS (SELECT 1 FROM ATENDIMENTO a WHERE a.ID_CLIENTE = 900);

-- D02 — Excluir um produto de teste: primeiro a linha do subtipo, depois o produto (ordem imposta pela FK).
DELETE FROM ARMACAO WHERE ID_PRODUTO = 9001;
DELETE FROM PRODUTO WHERE ID_PRODUTO = 9001;

-- D03 (comentado, falharia): apagar um cliente com atendimentos é bloqueado pela FK (RESTRICT).
-- DELETE FROM CLIENTE WHERE ID_CLIENTE = 1;   -- ERROR 1451: Cannot delete or update a parent row


-- =====================================================================
-- 8. CONSULTAS GERENCIAIS (G01 a G14)
-- Respondem aos problemas P1 a P5 e aos KPIs K1 a K14 (seção 1.6 do README).
-- =====================================================================

-- G01 — Quanto foi recebido por mês e por forma de pagamento?
-- Atende: P1 (dinheiro sem controle seguro); K1 (receita recebida)
SELECT DATE_FORMAT(DT_PAGAMENTO, '%Y-%m') AS mes, TP_FORMA,
       COUNT(*) AS pagamentos, SUM(VL_PAGAMENTO) AS receita_recebida
  FROM PAGAMENTO
 WHERE DT_PAGAMENTO >= @ini
 GROUP BY DATE_FORMAT(DT_PAGAMENTO, '%Y-%m'), TP_FORMA
 ORDER BY mes, TP_FORMA;

-- G02 — Quanto ainda falta receber das vendas não canceladas, por situação da venda?
-- Atende: P1 (saldo devedor da venda); K2 (saldo a receber)
SELECT COALESCE(v.CD_STATUS, 'TOTAL') AS situacao_da_venda,
       COUNT(*) AS vendas_com_saldo,
       SUM(t.VL_TOTAL - COALESCE(pg.pago, 0)) AS saldo_a_receber
  FROM VENDA v
  JOIN vw_venda_total t ON t.ID_VENDA = v.ID_VENDA
  LEFT JOIN (SELECT ID_VENDA, SUM(VL_PAGAMENTO) AS pago FROM PAGAMENTO GROUP BY ID_VENDA) pg ON pg.ID_VENDA = v.ID_VENDA
 WHERE v.CD_STATUS <> 'CANCELADO'
   AND t.VL_TOTAL - COALESCE(pg.pago, 0) > 0
 GROUP BY v.CD_STATUS WITH ROLLUP;

-- G03 — Quantas parcelas já venceram, quantas estão atrasadas e qual o valor atrasado, por semana de vencimento?
-- Atende: P1 (parcelas sem controle); K3 (parcelas atrasadas)
SELECT YEARWEEK(DT_VENCIMENTO, 3) AS semana, MIN(DT_VENCIMENTO) AS primeiro_vencimento,
       COUNT(*) AS parcelas_vencidas,
       SUM(ID_PAGAMENTO IS NULL) AS atrasadas,
       ROUND(100 * SUM(ID_PAGAMENTO IS NULL) / COUNT(*), 1) AS pct_atrasadas,
       COALESCE(SUM(CASE WHEN ID_PAGAMENTO IS NULL THEN VL_PARCELA END), 0) AS valor_atrasado
  FROM vw_parcela_situacao
 WHERE DT_VENCIMENTO < @hoje
 GROUP BY YEARWEEK(DT_VENCIMENTO, 3)
 ORDER BY semana;

-- G04 — Qual o ticket médio das vendas por mês?
-- Atende: P1 (valor das vendas); K4 (ticket médio)
SELECT DATE_FORMAT(v.DH_COMPRA, '%Y-%m') AS mes, COUNT(*) AS vendas,
       ROUND(AVG(t.VL_TOTAL), 2) AS ticket_medio, SUM(t.VL_TOTAL) AS valor_vendido
  FROM VENDA v
  JOIN vw_venda_total t ON t.ID_VENDA = v.ID_VENDA
 WHERE v.CD_STATUS <> 'CANCELADO' AND t.VL_TOTAL > 0 AND v.DH_COMPRA >= @ini
 GROUP BY DATE_FORMAT(v.DH_COMPRA, '%Y-%m')
 ORDER BY mes;

-- G05 — Quais tipos de produto estão abaixo do estoque mínimo hoje (100 pares de lentes, 500 armações)?
-- Atende: P2 (estoque sem controle de saldo e de mínimo); K5 (itens abaixo do mínimo, RN-34)
WITH saldo_produto AS (
  SELECT p.ID_PRODUTO, p.CD_TIPO,
         COALESCE(SUM(CASE e.CD_DIRECAO WHEN 'ENTRADA' THEN e.QT_MOVIMENTO ELSE -e.QT_MOVIMENTO END), 0) AS saldo
    FROM PRODUTO p
    JOIN (SELECT ID_PRODUTO FROM LENTE UNION SELECT ID_PRODUTO FROM ARMACAO) sub ON sub.ID_PRODUTO = p.ID_PRODUTO
    LEFT JOIN ESTOQUE e ON e.ID_PRODUTO = p.ID_PRODUTO AND e.CD_CONDICAO = 'DISPONIVEL' AND e.DT_MOVIMENTO <= @hoje
   GROUP BY p.ID_PRODUTO, p.CD_TIPO
)
SELECT s.CD_TIPO, u.CD_UNIDADE AS unidade,
       SUM(s.saldo) AS saldo_disponivel,
       CASE s.CD_TIPO WHEN 'LENTE' THEN 100 ELSE 500 END AS minimo,
       SUM(s.saldo) - CASE s.CD_TIPO WHEN 'LENTE' THEN 100 ELSE 500 END AS diferenca,
       CASE WHEN SUM(s.saldo) < CASE s.CD_TIPO WHEN 'LENTE' THEN 100 ELSE 500 END THEN 'REPOR' ELSE 'OK' END AS situacao,
       SUM(s.saldo <= 0) AS produtos_sem_saldo, COUNT(*) AS produtos_cadastrados
  FROM saldo_produto s
  JOIN (SELECT DISTINCT CD_TIPO, CD_UNIDADE FROM vw_produto_unidade) u ON u.CD_TIPO = s.CD_TIPO
 GROUP BY s.CD_TIPO, u.CD_UNIDADE
 ORDER BY s.CD_TIPO;

-- G06 — Qual o giro de estoque do período, por tipo de produto (saídas por venda ÷ saldo médio)?
-- Atende: P2 (produtos que giram devagar); K6 (giro de estoque)
WITH mov AS (
  SELECT p.CD_TIPO, e.DT_MOVIMENTO, e.CD_MOTIVO,
         CASE e.CD_DIRECAO WHEN 'ENTRADA' THEN e.QT_MOVIMENTO ELSE -e.QT_MOVIMENTO END AS delta
    FROM ESTOQUE e JOIN PRODUTO p ON p.ID_PRODUTO = e.ID_PRODUTO
   WHERE e.CD_CONDICAO = 'DISPONIVEL' AND e.DT_MOVIMENTO <= @hoje
), res AS (
  SELECT CD_TIPO,
         SUM(CASE WHEN DT_MOVIMENTO >= @ini AND CD_MOTIVO = 'VENDA' THEN -delta ELSE 0 END) AS saidas_venda,
         SUM(CASE WHEN DT_MOVIMENTO < @ini THEN delta ELSE 0 END) AS saldo_inicial,
         SUM(delta) AS saldo_final
    FROM mov GROUP BY CD_TIPO
)
SELECT CD_TIPO, saidas_venda, saldo_inicial, saldo_final,
       ROUND((saldo_inicial + saldo_final) / 2, 1) AS saldo_medio,
       ROUND(saidas_venda / ((saldo_inicial + saldo_final) / 2), 2) AS giro_no_periodo,
       ROUND(saidas_venda / ((saldo_inicial + saldo_final) / 2) * 365 / (DATEDIFF(@hoje, @ini) + 1), 1) AS giro_anualizado
  FROM res
 ORDER BY CD_TIPO;

-- G07 — Qual o prazo médio de entrega de cada fornecedor?
-- Atende: P2 (reposição); K7 (prazo médio de entrega)
SELECT f.ID_FORNECEDOR, f.NM_FORNECEDOR, COUNT(*) AS compras_recebidas,
       ROUND(AVG(DATEDIFF(c.DT_CHEGADA, c.DT_PEDIDO)), 1) AS prazo_medio_dias,
       MIN(DATEDIFF(c.DT_CHEGADA, c.DT_PEDIDO)) AS menor_prazo, MAX(DATEDIFF(c.DT_CHEGADA, c.DT_PEDIDO)) AS maior_prazo
  FROM COMPRA c
  JOIN FORNECEDOR f ON f.ID_FORNECEDOR = c.ID_FORNECEDOR
 WHERE c.CD_STATUS = 'RECEBIDA' AND c.DT_PEDIDO >= @ini
 GROUP BY f.ID_FORNECEDOR, f.NM_FORNECEDOR
 ORDER BY prazo_medio_dias DESC;

-- G08 — Quais garantias vencem nos próximos 30 dias (armação: 1 ano; lente: 6 meses, desde a montagem)?
-- Atende: P3 (garantia por produto vendido); K8 (garantias a vencer, RN-07)
SELECT v.ID_VENDA, c.NM_CLIENTE, COALESCE(c.NR_TELEFONE_CELULAR, c.NR_TELEFONE_FIXO) AS contato,
       p.CD_TIPO, p.DS_REFERENCIA, v.DT_MONTAGEM_FINALIZACAO AS montagem,
       DATE_ADD(v.DT_MONTAGEM_FINALIZACAO, INTERVAL CASE p.CD_TIPO WHEN 'LENTE' THEN 6 ELSE 12 END MONTH) AS fim_garantia
  FROM VENDA v
  JOIN CONTEM ct      ON ct.ID_VENDA = v.ID_VENDA
  JOIN PRODUTO p      ON p.ID_PRODUTO = ct.ID_PRODUTO
  JOIN ATENDIMENTO a  ON a.ID_ATENDIMENTO = v.ID_ATENDIMENTO
  JOIN CLIENTE c      ON c.ID_CLIENTE = a.ID_CLIENTE
 WHERE v.CD_STATUS = 'RETIRADO' AND v.DT_MONTAGEM_FINALIZACAO IS NOT NULL
   AND DATE_ADD(v.DT_MONTAGEM_FINALIZACAO, INTERVAL CASE p.CD_TIPO WHEN 'LENTE' THEN 6 ELSE 12 END MONTH)
       BETWEEN @hoje AND DATE_ADD(@hoje, INTERVAL 30 DAY)
 ORDER BY fim_garantia, v.ID_VENDA;

-- G09 — Qual a taxa de trocas e devoluções sobre as vendas de cada mês (pela nota da venda de origem)?
-- Atende: P3 (pós-venda); K9 (taxa de trocas e devoluções)
SELECT vm.mes, vm.vendas,
       COALESCE(oc.trocas, 0) AS trocas, COALESCE(oc.devolucoes, 0) AS devolucoes,
       ROUND(100 * (COALESCE(oc.trocas, 0) + COALESCE(oc.devolucoes, 0)) / vm.vendas, 1) AS pct_ocorrencias
  FROM (SELECT DATE_FORMAT(DH_COMPRA, '%Y-%m') AS mes, COUNT(*) AS vendas
          FROM VENDA WHERE CD_STATUS <> 'CANCELADO' AND DH_COMPRA >= @ini
         GROUP BY DATE_FORMAT(DH_COMPRA, '%Y-%m')) vm
  LEFT JOIN (SELECT DATE_FORMAT(v.DH_COMPRA, '%Y-%m') AS mes,
                    SUM(t.TP_OCORRENCIA = 'TROCA') AS trocas, SUM(t.TP_OCORRENCIA = 'DEVOLUCAO') AS devolucoes
               FROM TROCA_DEVOLUCAO t
               JOIN NOTA_FISCAL_SAIDA n ON n.ID_NOTA_SAIDA = t.ID_NOTA_SAIDA
               JOIN PAGAMENTO p         ON p.ID_PAGAMENTO = n.ID_PAGAMENTO
               JOIN VENDA v             ON v.ID_VENDA = p.ID_VENDA
              GROUP BY DATE_FORMAT(v.DH_COMPRA, '%Y-%m')) oc ON oc.mes = vm.mes
 ORDER BY vm.mes;

-- G10 — Quantos atendimentos viraram venda em cada semana (conversão)?
-- Atende: P4 (conversão não medida); K10 (conversão de atendimentos, referência ≈ 80%)
SELECT YEARWEEK(a.DH_ATENDIMENTO, 3) AS semana, MIN(DATE(a.DH_ATENDIMENTO)) AS inicio,
       COUNT(*) AS atendimentos, COUNT(v.ID_VENDA) AS vendas,
       ROUND(100 * COUNT(v.ID_VENDA) / COUNT(*), 1) AS pct_conversao
  FROM ATENDIMENTO a
  LEFT JOIN VENDA v ON v.ID_ATENDIMENTO = a.ID_ATENDIMENTO AND v.CD_STATUS <> 'CANCELADO'
 WHERE a.DH_ATENDIMENTO >= @ini
 GROUP BY YEARWEEK(a.DH_ATENDIMENTO, 3)
 ORDER BY semana;

-- G11 — Qual a taxa de aprovação dos orçamentos emitidos em cada mês?
-- Atende: P4 (orçamentos que não viram venda); K11 (aprovação de orçamentos)
SELECT DATE_FORMAT(DH_EMISSAO, '%Y-%m') AS mes, COUNT(*) AS orcamentos_emitidos,
       SUM(CD_STATUS = 'APROVADO') AS aprovados, SUM(CD_STATUS = 'RECUSADO') AS recusados,
       SUM(CD_STATUS IN ('EMITIDO', 'CANCELADO')) AS sem_decisao_ou_cancelados,
       ROUND(100 * SUM(CD_STATUS = 'APROVADO') / COUNT(*), 1) AS pct_aprovacao
  FROM ORCAMENTO
 WHERE CD_STATUS <> 'EM_ELABORACAO' AND DH_EMISSAO >= @ini
 GROUP BY DATE_FORMAT(DH_EMISSAO, '%Y-%m')
 ORDER BY mes;

-- G12 — Qual a conversão de cada funcionário nos atendimentos comerciais, por mês?
-- Atende: P4 (desempenho por consultor); K12 (conversão por consultor)
SELECT DATE_FORMAT(a.DH_ATENDIMENTO, '%Y-%m') AS mes, f.NM_FUNCIONARIO, f.TP_FUNCAO,
       COUNT(*) AS atendimentos_comerciais, COUNT(v.ID_VENDA) AS vendas,
       ROUND(100 * COUNT(v.ID_VENDA) / COUNT(*), 1) AS pct_conversao
  FROM ATENDIMENTO a
  JOIN FUNCIONARIO f ON f.ID_FUNCIONARIO = a.ID_FUNCIONARIO
  LEFT JOIN VENDA v  ON v.ID_ATENDIMENTO = a.ID_ATENDIMENTO AND v.CD_STATUS <> 'CANCELADO'
 WHERE a.TP_ATENDIMENTO = 'COMERCIAL' AND a.DH_ATENDIMENTO >= @ini
 GROUP BY DATE_FORMAT(a.DH_ATENDIMENTO, '%Y-%m'), f.ID_FUNCIONARIO, f.NM_FUNCIONARIO, f.TP_FUNCAO
 ORDER BY mes, pct_conversao DESC;

-- G13 — Que proporção das vendas de lente de grau tem receita registrada no atendimento?
-- Atende: P5 (receita obrigatória, RN-16); K13 (conformidade de receita, meta 100%)
SELECT x.mes, COUNT(*) AS vendas_lente_de_grau, SUM(x.tem_receita) AS com_receita,
       ROUND(100 * SUM(x.tem_receita) / COUNT(*), 1) AS pct_conformidade
  FROM (SELECT DATE_FORMAT(v.DH_COMPRA, '%Y-%m') AS mes, v.ID_VENDA,
               EXISTS (SELECT 1 FROM RECEITA r WHERE r.ID_ATENDIMENTO = v.ID_ATENDIMENTO) AS tem_receita
          FROM VENDA v
         WHERE v.CD_STATUS <> 'CANCELADO' AND v.DH_COMPRA >= @ini
           AND EXISTS (SELECT 1 FROM CONTEM ct JOIN LENTE l ON l.ID_PRODUTO = ct.ID_PRODUTO
                        WHERE ct.ID_VENDA = v.ID_VENDA AND l.IN_POSSUI_GRAU = TRUE)) x
 GROUP BY x.mes
 ORDER BY x.mes;

-- G14 — Que proporção das vendas inclui armação e lente (venda completa) em cada mês?
-- Atende: K14 (venda completa, referência ≈ 75%); apoia P4 (qualidade da venda)
SELECT DATE_FORMAT(v.DH_COMPRA, '%Y-%m') AS mes, COUNT(*) AS vendas,
       SUM(EXISTS (SELECT 1 FROM CONTEM c1 JOIN PRODUTO p1 ON p1.ID_PRODUTO = c1.ID_PRODUTO WHERE c1.ID_VENDA = v.ID_VENDA AND p1.CD_TIPO = 'ARMACAO')
           AND EXISTS (SELECT 1 FROM CONTEM c2 JOIN PRODUTO p2 ON p2.ID_PRODUTO = c2.ID_PRODUTO WHERE c2.ID_VENDA = v.ID_VENDA AND p2.CD_TIPO = 'LENTE')) AS vendas_completas,
       ROUND(100 * SUM(EXISTS (SELECT 1 FROM CONTEM c1 JOIN PRODUTO p1 ON p1.ID_PRODUTO = c1.ID_PRODUTO WHERE c1.ID_VENDA = v.ID_VENDA AND p1.CD_TIPO = 'ARMACAO')
           AND EXISTS (SELECT 1 FROM CONTEM c2 JOIN PRODUTO p2 ON p2.ID_PRODUTO = c2.ID_PRODUTO WHERE c2.ID_VENDA = v.ID_VENDA AND p2.CD_TIPO = 'LENTE')) / COUNT(*), 1) AS pct_completas
  FROM VENDA v
 WHERE v.CD_STATUS <> 'CANCELADO' AND v.DH_COMPRA >= @ini
   AND EXISTS (SELECT 1 FROM CONTEM c WHERE c.ID_VENDA = v.ID_VENDA)
 GROUP BY DATE_FORMAT(v.DH_COMPRA, '%Y-%m')
 ORDER BY mes;


-- =====================================================================
-- 9. CONSULTAS DE AUDITORIA (A01 a A12)
-- Cada uma lista as linhas que violam uma regra que o banco não declara
-- sozinho (seção 1.5 do README). Resultado vazio = regra respeitada.
-- A massa de dados traz de propósito alguns casos de violação, para a
-- demonstração mostrar o que cada auditoria encontra.
-- =====================================================================

-- A01 — Existe pagamento registrado sem nota fiscal de saída?
-- Verifica: RN-22 (a ótica emite uma nota a cada pagamento recebido)
SELECT p.ID_PAGAMENTO, p.ID_VENDA, p.DT_PAGAMENTO, p.TP_FINALIDADE, p.VL_PAGAMENTO
  FROM PAGAMENTO p
  LEFT JOIN NOTA_FISCAL_SAIDA n ON n.ID_PAGAMENTO = p.ID_PAGAMENTO
 WHERE n.ID_NOTA_SAIDA IS NULL
 ORDER BY p.DT_PAGAMENTO, p.ID_PAGAMENTO;

-- A02 — Existe compra (não cancelada) sem nota fiscal de entrada?
-- Verifica: RN-35 (toda compra tem exatamente uma nota de entrada; a cancelada não recebe nota)
SELECT c.ID_COMPRA, c.DT_PEDIDO, c.DT_CHEGADA, c.CD_STATUS, f.NM_FORNECEDOR
  FROM COMPRA c
  JOIN FORNECEDOR f ON f.ID_FORNECEDOR = c.ID_FORNECEDOR
  LEFT JOIN NOTA_FISCAL_ENTRADA n ON n.ID_COMPRA = c.ID_COMPRA
 WHERE n.ID_NOTA_ENTRADA IS NULL AND c.CD_STATUS <> 'CANCELADA'
 ORDER BY c.DT_PEDIDO;

-- A03 — Existe venda com pagamentos acima do total das linhas?
-- Verifica: RN-11 (recebimentos não excedem o saldo devido)
SELECT v.ID_VENDA, v.CD_STATUS, t.VL_TOTAL, SUM(p.VL_PAGAMENTO) AS total_pago,
       SUM(p.VL_PAGAMENTO) - t.VL_TOTAL AS excesso
  FROM VENDA v
  JOIN vw_venda_total t ON t.ID_VENDA = v.ID_VENDA
  JOIN PAGAMENTO p      ON p.ID_VENDA = v.ID_VENDA
 GROUP BY v.ID_VENDA, v.CD_STATUS, t.VL_TOTAL
HAVING SUM(p.VL_PAGAMENTO) > t.VL_TOTAL
 ORDER BY excesso DESC;

-- A04 — Existe encomenda liberada sem sinal de pelo menos 30% do total até a data de liberação?
-- Verifica: RN-18 (encomenda só é liberada com sinal de 30% do total da venda)
SELECT v.ID_VENDA, v.DT_LIBERACAO_ENCOMENDA, t.VL_TOTAL,
       COALESCE(SUM(p.VL_PAGAMENTO), 0) AS recebido_ate_a_liberacao,
       ROUND(100 * COALESCE(SUM(p.VL_PAGAMENTO), 0) / t.VL_TOTAL, 1) AS pct_recebido
  FROM VENDA v
  JOIN vw_venda_total t ON t.ID_VENDA = v.ID_VENDA
  LEFT JOIN PAGAMENTO p ON p.ID_VENDA = v.ID_VENDA AND p.DT_PAGAMENTO <= v.DT_LIBERACAO_ENCOMENDA
 WHERE v.DT_LIBERACAO_ENCOMENDA IS NOT NULL AND t.VL_TOTAL > 0
 GROUP BY v.ID_VENDA, v.DT_LIBERACAO_ENCOMENDA, t.VL_TOTAL
HAVING COALESCE(SUM(p.VL_PAGAMENTO), 0) < 0.30 * t.VL_TOTAL
 ORDER BY pct_recebido;

-- A05 — Existe venda de lente de grau em atendimento sem receita?
-- Verifica: RN-16 (lente com grau exige receita no atendimento da venda)
SELECT v.ID_VENDA, v.DH_COMPRA, v.CD_STATUS, v.ID_ATENDIMENTO
  FROM VENDA v
 WHERE v.CD_STATUS <> 'CANCELADO'
   AND EXISTS (SELECT 1 FROM CONTEM ct JOIN LENTE l ON l.ID_PRODUTO = ct.ID_PRODUTO
                WHERE ct.ID_VENDA = v.ID_VENDA AND l.IN_POSSUI_GRAU = TRUE)
   AND NOT EXISTS (SELECT 1 FROM RECEITA r WHERE r.ID_ATENDIMENTO = v.ID_ATENDIMENTO)
 ORDER BY v.DH_COMPRA;

-- A06 — Existe produto sem linha em LENTE nem em ARMACAO?
-- Verifica: RN-14 (todo produto é LENTE ou ARMACAO)
SELECT p.ID_PRODUTO, p.CD_TIPO, p.DS_REFERENCIA
  FROM PRODUTO p
  LEFT JOIN LENTE l   ON l.ID_PRODUTO = p.ID_PRODUTO
  LEFT JOIN ARMACAO a ON a.ID_PRODUTO = p.ID_PRODUTO
 WHERE l.ID_PRODUTO IS NULL AND a.ID_PRODUTO IS NULL;

-- A07 — Existe saída de estoque maior que o saldo da condição movimentada?
-- Verifica: RN-12 (saída não pode exceder o saldo; disponível e segregado são separados)
SELECT x.ID_MOVIMENTO, x.DT_MOVIMENTO, x.ID_PRODUTO, x.CD_CONDICAO, x.CD_MOTIVO, x.QT_MOVIMENTO, x.saldo_apos
  FROM (SELECT e.*, SUM(CASE e.CD_DIRECAO WHEN 'ENTRADA' THEN e.QT_MOVIMENTO ELSE -e.QT_MOVIMENTO END)
                      OVER (PARTITION BY e.ID_PRODUTO, e.CD_CONDICAO ORDER BY e.DT_MOVIMENTO, e.ID_MOVIMENTO) AS saldo_apos
          FROM ESTOQUE e) x
 WHERE x.CD_DIRECAO = 'SAIDA' AND x.saldo_apos < 0
 ORDER BY x.DT_MOVIMENTO, x.ID_MOVIMENTO;

-- A08 — Existe receita sem nenhuma medida?
-- Verifica: RN-10 (cada receita tem de uma a quatro medidas)
SELECT r.ID_RECEITA, r.DT_RECEITA, r.TP_ORIGEM, r.ID_ATENDIMENTO
  FROM RECEITA r
  LEFT JOIN RECEITA_MEDIDA m ON m.ID_RECEITA = r.ID_RECEITA
 WHERE m.ID_RECEITA IS NULL
 ORDER BY r.ID_RECEITA;

-- A09 — Existe venda sem nenhuma linha em CONTEM?
-- Verifica: RN-04 (a venda é composta por linhas de produto; o total vem delas)
SELECT v.ID_VENDA, v.DH_COMPRA, v.CD_STATUS
  FROM VENDA v
  LEFT JOIN CONTEM ct ON ct.ID_VENDA = v.ID_VENDA
 WHERE ct.ID_VENDA IS NULL;

-- A10 — Existe pagamento de quitação com valor diferente do valor da parcela?
-- Verifica: RN-28 (o pagamento que quita uma parcela corresponde ao valor dela)
SELECT p.ID_PAGAMENTO, p.DT_PAGAMENTO, pa.ID_PARCELA, pa.NR_PARCELA, pa.VL_PARCELA, p.VL_PAGAMENTO,
       p.VL_PAGAMENTO - pa.VL_PARCELA AS diferenca
  FROM PAGAMENTO p
  JOIN PARCELA pa ON pa.ID_PARCELA = p.ID_PARCELA_QUITADA
 WHERE p.VL_PAGAMENTO <> pa.VL_PARCELA
 ORDER BY p.DT_PAGAMENTO;

-- A11 — Existe venda sem orçamento aprovado dentro da validade no mesmo atendimento?
-- Verifica: RN-23 (toda venda é precedida de orçamento aprovado e válido)
SELECT v.ID_VENDA, v.DH_COMPRA, v.ID_ATENDIMENTO,
       (SELECT GROUP_CONCAT(o.CD_STATUS ORDER BY o.DH_EMISSAO) FROM ORCAMENTO o WHERE o.ID_ATENDIMENTO = v.ID_ATENDIMENTO) AS orcamentos_do_atendimento
  FROM VENDA v
 WHERE NOT EXISTS (SELECT 1 FROM ORCAMENTO o
                    WHERE o.ID_ATENDIMENTO = v.ID_ATENDIMENTO AND o.CD_STATUS = 'APROVADO'
                      AND o.DH_APROVACAO <= o.DH_VALIDADE AND v.DH_COMPRA <= o.DH_VALIDADE)
 ORDER BY v.DH_COMPRA;

-- A12 — Existe venda cuja receita trazida pelo cliente tinha mais de um ano na data da compra?
-- Verifica: RN-03 (a ótica aceita receita trazida com até um ano de emissão)
SELECT v.ID_VENDA, DATE(v.DH_COMPRA) AS data_compra, r.ID_RECEITA, r.DT_RECEITA,
       DATEDIFF(DATE(v.DH_COMPRA), r.DT_RECEITA) AS dias_de_idade
  FROM VENDA v
  JOIN RECEITA r ON r.ID_ATENDIMENTO = v.ID_ATENDIMENTO
 WHERE r.TP_ORIGEM = 'TRAZIDA'
   AND r.DT_RECEITA < DATE_SUB(DATE(v.DH_COMPRA), INTERVAL 1 YEAR)
 ORDER BY dias_de_idade DESC;
